import {createChatSpeech} from './chat-speech.js';
import {renderCoachUI} from './chat-ui.js';
import {bindCurrencyPicker,bindEntrySuggestions,createWalkthrough} from './ui-helpers.js';
import {renderOverviewCharts,bindOverviewCharts} from './overview-charts.js';
import {mountTransactionGrid} from './transaction-grid.js';
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={voice:'M4 10v4m4-8v12m4-15v18m4-15v12m4-8v4',home:'M3 10l9-7 9 7v10H15v-6H9v6H3Z',overview:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',transactions:'M7 4h14M7 12h14M7 20h14M3 4h.01M3 12h.01M3 20h.01',budgets:'M4 5h16v15H4ZM8 2v6m8-6v6M4 10h16m-12 5h3m3 0h2',coach:'M21 11a8 8 0 0 1-8 8H8l-5 3v-8a8 8 0 1 1 18-3ZM8 10h8m-8 4h5',planning:'M3 20l6-7 4 3 8-12m-6 0h6v6',import:'M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6',entry:'M12 5v14m-7-7h14',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6M8 15v6',learn:'M12 5c-3-3-7-3-10-2v16c4-1 7-1 10 2 3-3 6-3 10-2V3c-3-1-7-1-10 2Zm0 0v16',arrow:'M5 12h14m-6-6 6 6-6 6',moon:'M20 15a9 9 0 0 1-11-11 9 9 0 1 0 11 11',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',menu:'M4 6h16M4 12h16M4 18h16',close:'M5 5l14 14M5 19 19 5',check:'M4 12l5 5L20 6',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0ZM5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8',stop:'M5 5h14v14H5Z',speaker:'M4 9h4l5-4v14l-5-4H4Zm13-2a7 7 0 0 1 0 10m-1-7a3 3 0 0 1 0 4',undo:'M4 9h10a6 6 0 1 1 0 12M4 9l5-5M4 9l5 5',download:'M12 3v13m-5-5 5 5 5-5M3 17v4h18v-4',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6ZM8 12l3 3 5-6'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.home}"/></svg>`;
const routes=[['overview','Overview'],['transactions','Transactions'],['budgets','Budgets'],['coach','Coach'],['planning','Planning & goals'],['import','Import data'],['entry','Add transaction'],['learn','Learn'],['settings','Settings']];
let state,scope={currency:null,month:null},report,setupDraft=null,fileDraft=null,importResult=null,pending=null,busy=false,chat=[],chatDraft='',useAI=false,chatSettingsOpen=false,chatPending=false,planningResult=null,importRequest=null,importAllRows=[],importExclusions=[],taxDraft=[],importKind='Transactions',selectedSheet=null,chatDrawerOpen=false,newRecordIds=new Set(),chatExpanded=false,gridRecords=[];
const speech=createChatSpeech({getState:()=>state,getScope:()=>({...scope}),getPage:()=>'/'+route(),getDraft:()=>chatDraft,
 setDraft:text=>{chatDraft=text;if($('#chat-text'))$('#chat-text').value=text;},icon,escape:E,
 request:async(path,body,{signal}={})=>{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-HomeAccounts-Token':state.csrf},body:JSON.stringify(body),signal});const result=await response.json();if(!response.ok){const error=new Error(result.error||'Speech service unavailable.');error.userMessage=error.message;throw error;}return result;},
 onTranscript:message=>{chat.push(message);renderChat();},
 onRequest:async({text,context},{signal})=>{
  const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json','X-HomeAccounts-Token':state.csrf},body:JSON.stringify({text,currency:context.currency,month:context.month,reference_date:state.today,use_ai:false}),signal});
  const result=await response.json();if(!response.ok||signal.aborted||!speech.live.active)throw new Error('Voice request stopped.');
  if(result.review){speech.live.setMuted(true);chat.push({role:'assistant',content:result.answer,links:result.links,review:result.review});renderChat();openReview(result.review);}
  return {answer:result.answer,reviewNeedsConfirmation:Boolean(result.review)};
 },changed:()=>{if($('#chat-send'))$('#chat-send').disabled=chatPending||speech.active||!chatDraft.trim()||chatDraft.length>6000;}
});
const voice=speech.voice;
const route=()=>location.pathname.slice(1)||state?.settings.home||'overview';
const field=(label,name,value='',type='text',opts={})=>`<div class="${opts.full?'full':''}"><label for="${E(opts.id||name)}">${E(label)}</label><input id="${E(opts.id||name)}" name="${E(name)}" type="${E(type)}" value="${E(value)}" ${opts.required?'required':''} ${opts.readOnly?'readonly aria-readonly="true"':''} ${opts.min!==undefined?`min="${E(opts.min)}"`:''} ${opts.step?`step="${E(opts.step)}"`:''} ${opts.placeholder?`placeholder="${E(opts.placeholder)}"`:''} ${opts.suggest?'data-suggest':''}>${opts.hint?`<p class="field-hint">${E(opts.hint)}</p>`:''}</div>`;
const select=(label,name,options,value='',opts={})=>`<div><label for="${E(opts.id||name)}">${E(label)}</label><select id="${E(opts.id||name)}" name="${E(name)}" ${opts.required?'required':''}>${options.map(option=>{const o=typeof option==='string'?{value:option,label:option}:option;return `<option value="${E(o.value)}" ${String(value)===String(o.value)?'selected':''}>${E(o.label)}</option>`;}).join('')}</select></div>`;
const button=(text,name='entry',cls='primary',extra='')=>`<button class="${cls}" data-go="/${name}" ${extra}>${icon(name)}${E(text)}</button>`;
const link=(text,href,cls='button')=>`<a class="${cls}" href="${E(href)}" data-route>${E(text)}${icon('arrow')}</a>`;
function toast(text){const node=$('#toast');node.textContent=text;node.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.style.display='none',4500);}
async function api(path,body){const response=await fetch(path,{headers:body?{'Content-Type':'application/json','X-HomeAccounts-Token':state?.csrf||''}:{},method:body?'POST':'GET',body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed.');return result;}
async function action(fn,node){if(busy)return;busy=true;if(node)node.disabled=true;try{await fn();}catch(error){toast(error.message);const target=$('#page-error');if(target){target.hidden=false;target.textContent=error.message;}}finally{busy=false;if(node?.isConnected)node.disabled=false;}}
function initialScope(){const query=new URLSearchParams(location.search);let currency=query.get('currency')||scope.currency||state.settings.currency;if(!state.currencies.some(c=>c.code===currency))currency=null;const months=[...new Set(state.transactions.filter(t=>t.currency===currency).map(t=>t.date.slice(0,7)))].sort().reverse();const budgets=[...new Set(state.budgets.filter(b=>b.currency===currency).map(b=>b.period))].sort().reverse();scope={currency,month:query.get('month')||scope.month||months[0]||budgets[0]||state.today.slice(0,7)};}
async function refresh(){state=await api('/api/state');initialScope();document.documentElement.dataset.theme=state.settings.theme;}
async function go(href,replace=false,touring=false){speech.stop();closeChat(false);$('#entry-dialog').close();if(!touring)walkthrough.stop();const url=new URL(href,location.origin);if(url.origin!==location.origin)return;history[replace?'replaceState':'pushState']({},'',url.pathname+url.search);initialScope();await render();$('#main h1')?.focus({preventScroll:true});window.scrollTo(0,0);}
const nav=(id,title)=>`<a class="nav-link" href="/${id}" data-route ${route()===id?'aria-current="page"':''}>${icon(id)}${title}</a>`;
function shell(){return `<aside class="sidebar" id="navigation" aria-label="Workspace navigation"><button class="menu-close" id="menu-close" aria-label="Close menu">${icon('close')}</button><a class="brand" href="/" data-route><span class="brand-mark">${icon('home')}</span>Home Accounts</a><nav class="nav-group"><div class="eyebrow nav-label">Your workspace</div>${routes.slice(0,5).filter(r=>r[0]!=='coach').map(r=>nav(...r)).join('')}<div class="eyebrow nav-label" style="margin-top:20px">Manage & explore</div>${routes.slice(5).filter(r=>r[0]!=='coach').map(r=>nav(...r)).join('')}</nav><div class="side-foot"><span class="status-dot"></span>Stored on this computer<br><span>${state.transactions.length} confirmed records</span></div></aside><div class="workspace"><header class="topbar"><button class="mobile-toggle" id="menu-open" aria-label="Open menu" aria-controls="navigation" aria-expanded="false">${icon('menu')}</button><span class="eyebrow current-page">${E(routes.find(r=>r[0]===route())?.[1]||'Field setup')}</span><div class="scope"><div class="scope-field currency-field"><label for="scope-currency">Currency</label><div class="currency-picker"><input id="scope-currency" role="combobox" aria-label="Reporting currency" aria-autocomplete="list" aria-controls="currency-options" aria-expanded="false" autocomplete="off" value="${E(scope.currency||'')}" placeholder="Search currency" title="Search by country, currency name or code"><div id="currency-options" role="listbox" aria-label="Currencies" hidden></div></div></div><div class="scope-field"><label for="scope-month">Month</label><input id="scope-month" type="month" aria-label="Reporting month" value="${E(scope.month)}" min="0001-01" max="9999-12"></div></div><div class="top-actions"><button class="subtle workspace-info" id="workspace-info" title="Records are stored on this computer" aria-label="About this local workspace">${icon('shield')}<span>Local workspace</span></button><button class="subtle theme-toggle" id="theme-cycle" title="Switch visual mode: light, dark or bright" aria-label="Change visual mode">${icon(state.settings.theme==='dark'?'moon':'sun')}</button><button id="help-walkthrough" title="Learn how to use this page" aria-label="Help walkthrough">${icon('learn')}<span>Help</span></button><button id="open-chat" title="Open the Home Accounts chat panel" aria-label="Open chat" aria-controls="chat-drawer" aria-expanded="${chatDrawerOpen}">${icon('coach')}<span>Chat</span></button></div></header><main id="main" class="content"><div id="page-error" class="notice error" role="alert" hidden></div><div id="page"></div><footer class="footer">Home Accounts · Your confirmed records, your decisions · Currencies stay separate</footer></main></div><nav class="bottom-nav" aria-label="Mobile navigation">${routes.filter(r=>['overview','transactions','budgets','planning'].includes(r[0])).map(([id,title])=>`<a href="/${id}" data-route ${route()===id?'aria-current="page"':''}>${icon(id)}${title}</a>`).join('')}</nav>`;}
function head(title,subtitle,actions=''){return `<div class="page-head"><div><p class="eyebrow">Your money, considered</p><h1 tabindex="-1">${E(title)}</h1><p>${E(subtitle)}</p></div><div class="actions">${actions}</div></div>`;}
function metric(title,value,note,cls=''){return `<article class="card stat"><div class="stat-label">${E(title)}</div><div class="stat-value ${cls}">${E(value)}</div><div class="stat-note">${E(note)}</div></article>`;}
function currencyRequired(){return `<div class="card empty"><div class="empty-icon">${icon('settings')}</div><h2>Choose your currency</h2><p>Select a reporting currency above. Existing records keep their currency; amounts are never converted.</p></div>`;}
function money(value){return `${scope.currency} ${new Intl.NumberFormat('en-US',{minimumFractionDigits:state.currencies.find(c=>c.code===scope.currency)?.digits??2,maximumFractionDigits:4}).format(value)}`;}
function recordTable(rows,editable=false){if(editable){gridRecords=rows;return '<div id="transaction-grid"></div>';} if(!rows.length)return '<p class="muted">No matching records.</p>';const custom=state.schema.fields.filter(f=>f.included&&f.key.startsWith('custom_'));const label=k=>state.schema.fields.find(f=>f.key===k)?.label||k;return `<div class="table-wrap"><table><thead><tr>${['date','type','description','category','subcategory','amount','currency','account'].map(k=>`<th>${E(label(k))}</th>`).join('')}${custom.map(f=>`<th>${E(f.label)}</th>`).join('')}${editable?'<th>Actions</th>':''}</tr></thead><tbody>${rows.map(t=>`<tr data-transaction-id="${E(t.id)}" class="${newRecordIds.has(t.id)?'just-added':''}">${['date','type','description','category','subcategory','amount','currency','account'].map(k=>`<td title="${E(t[k])}">${E(t[k])}</td>`).join('')}${custom.map(f=>`<td>${E(JSON.parse(t.custom_fields||'{}')[f.key]??'')}</td>`).join('')}${editable?`<td><button data-edit="${E(t.id)}">Edit</button> <button class="danger" data-delete="${E(t.id)}">Remove</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function drill(month,category=''){return `/transactions?${new URLSearchParams({month,currency:scope.currency,...(category?{category}:{})})}`;}
function clearTransactionsButton(id){return `<button class="danger" id="${id}" data-clear-transactions ${state.transactions.length?'':'disabled'}>Clear all transactions</button>`;}
function overviewChartData(){return {transactions:state.transactions,budgets:state.budgets,currency:scope.currency,month:scope.month,currencyDigits:state.currencies.find(item=>item.code===scope.currency)?.digits??2};}
function overviewContent(){const r=report;const intro=head('A clearer picture.','Add a transaction or import your file, then explore confirmed income, spending and budgets for '+scope.month+'.',button('Add transaction')+clearTransactionsButton('clear-transactions-top'));if(!r.count){let message='You have not confirmed any transactions yet. Field setup creates your workspace; it does not import your records. Prepare, review and confirm an import, or add your first entry.';if(r.all_count&&r.record_currencies.includes(scope.currency))message=`No ${scope.currency} records in ${scope.month}. Choose a populated month or open the latest recorded month.`;else if(r.all_count)message=`Your confirmed records use ${r.record_currencies.join(', ')}. Choose one of those currencies or add records in ${scope.currency}.`;return intro+`<section class="card empty"><div class="empty-icon">${icon('overview')}</div><p class="eyebrow">A starting point, not zero spending</p><h2>${r.all_count?'No records in this selection':'Make room for your first record'}</h2><p>${E(message)}</p><div class="actions">${button('Import transactions','import')}${button('Add an entry','entry','')}${r.months.length?link('Latest recorded month',`/overview?currency=${scope.currency}&month=${r.months.at(-1).month}`):''}</div></section>${r.budget?`<div class="card" style="margin-top:20px"><h2>Planned budget: ${E(r.budget.display)}</h2><p class="muted">Confirm transactions before assessing spending.</p>${link('Review budgets','/budgets')}</div>`:''}`;}
 return intro+`<section class="hero"><div><p class="eyebrow">${E(scope.currency)} · ${scope.month}</p><h2>Every record adds clarity.</h2><p>${r.count} confirmed transactions in this selection. Explore the records behind any chart, then choose your next step.</p></div><div class="hero-icon">${icon('planning')}</div></section><section class="grid stats">${metric('Confirmed income',r.income.display,'Income records only')}${metric('Net expenses',r.expenses.display,'Expenses minus refunds')}${metric('Recorded surplus',r.surplus.display,'Income − net expenses',r.surplus.minor>=0?'positive':'negative')}${metric('Budget remaining',r.remaining?.display||'Not set',r.budget?'Plan: '+r.budget.display:'Budgets are optional',r.remaining?.minor<0?'negative':'')}</section>${renderOverviewCharts(overviewChartData())}<section class="card"><div class="card-head"><div><h2>Recent activity</h2><p>Only ${scope.month} · ${scope.currency}</p></div>${link('View transactions',drill(scope.month),'')}</div>${r.recent.map(t=>`<button class="row-click ${newRecordIds.has(t.id)?'just-added':''}" data-transaction-id="${E(t.id)}" data-edit="${E(t.id)}"><span class="row-main"><span class="row-icon">${icon(t.type==='income'?'planning':t.type==='transfer'?'arrow':'transactions')}</span><span><span class="row-title">${E(t.merchant||t.description||t.type)}</span><br><small>${E(t.date)} · ${E(t.category)}</small></span></span><span class="row-amount ${t.type==='income'?'positive':''}">${E(t.amount)} ${t.currency}<br><small>${E(t.type)}</small></span></button>`).join('')}</section><p class="footnote">Read-only summary. Refunds reduce spending; transfers are excluded. Recorded surplus is not proof of saving or investing. Budget remaining = planned limits − all net expenses; parent and child limits are not added twice.</p>`;}
function overviewPage(){return newRecordsNotice()+overviewContent()+(!report.count?renderOverviewCharts(overviewChartData()):'')+`<section class="card reset-transactions"><div><h2>Start again</h2><p class="muted">Clear all transactions across every month and currency. Budgets, fields and settings stay in place. You can undo the clearing or import your file again.</p>${!state.transactions.length?'<p class="field-hint">There are no transactions to clear.</p>':''}</div><div class="actions">${clearTransactionsButton('clear-transactions')}${state.history.length?link('Review undo','/settings'):''}</div></section>`;}
function transactionPage(){const q=new URLSearchParams(location.search),category=q.get('category')||'',type=q.get('type')||'',search=q.get('search')||'',all=q.get('all')==='1';const categories=[...new Set([...state.transactions.map(t=>t.category),...state.budgets.map(b=>b.category),...(category?[category]:[])])].sort();const records=state.transactions.filter(t=>t.currency===scope.currency&&(all||t.date.startsWith(scope.month))&&(!category||t.category===category)&&(!type||t.type===type)&&(!search||Object.values(t).join(' ').toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));return newRecordsNotice()+head('Your records. Your story.','Add a transaction, apply filters to find a record, or use Edit and Remove to review a change.',button('Add transaction'))+`<section class="card"><form id="filters"><div class="filters">${field('Search particulars, merchant or ID','search',search,'search')}${select('Category','category',[{value:'',label:'All categories'},...categories],category)}${select('Transaction type','type',[{value:'',label:'All types'},'income','expense','transfer'],type)}</div><div class="actions"><label class="check"><input type="checkbox" name="all" ${all?'checked':''}>All recorded months</label><button class="primary">Apply filters</button><button type="button" id="export-transactions">${icon('download')}Export filtered CSV</button></div></form><p class="footnote" style="margin-bottom:18px">${records.length} records · ${E(scope.currency)}${all?' · all months':' · '+scope.month}. Negative expenses are refunds.</p>${recordTable(records,true)}</section><p class="footnote">Edits and removals open a preview. Nothing changes until you confirm. Full record IDs are preserved in CSV exports.</p>`;}
function budgetPage(){return head('A little intention goes a long way.','Set a monthly limit using the same categories as your expenses, then compare planned and actual spending.',`<button class="primary" id="new-budget">${icon('entry')}Set a budget</button>`)+`<section class="grid stats">${metric('Planned this month',report.budget?.display||'Not set','Category limits without double counting')}${metric('Net spending',report.expenses.display,'Confirmed expenses minus refunds')}${metric('Remaining',report.remaining?.display||'Not set','Plan minus all net expenses',report.remaining?.minor<0?'negative':'')}${metric('Category limits',report.budgets.length,'Parent limits include their children')}</section><section class="card"><div class="card-head"><div><h2>Your monthly limits</h2><p>${scope.month} · ${scope.currency}. Limits never increase automatically.</p></div><button id="new-budget-mobile">${icon('entry')}Set a budget</button></div>${report.budgets.map(b=>{const planned=Number(b.amount),spent=Number(b.spent.amount);return `<div class="budget-row"><div class="row" style="border:0;padding:0"><div><h3>${E(b.category)}${b.subcategory?' / '+E(b.subcategory):''}</h3><small>${E(b.spent.display)} spent of ${E(b.currency+' '+b.amount)}</small></div><div class="actions"><span class="${b.remaining.minor<0?'negative':'positive'}">${E(b.remaining.display)} left</span><button data-budget="${E(b.id)}">Adjust</button></div></div><div class="progress"><span style="width:${Math.max(0,Math.min(100,planned?spent/planned*100:spent?100:0))}%;${b.remaining.minor<0?'background:var(--negative)':''}"></span></div></div>`;}).join('')||`<div class="empty"><div class="empty-icon">${icon('budgets')}</div><h2>Start with one useful limit</h2><p>Choose a category and monthly amount. You can still record genuine overspending.</p></div>`}<div class="actions" style="margin-top:20px"><button id="export-budgets">${icon('download')}Export budgets CSV</button>${link('Import monthly budgets','/import?kind=Budgets')}</div></section><p class="footnote">Category limits include all subcategories. Parent and child limits are never summed twice. A zero limit is a real budget; no limit is shown as not set.</p>`;}
function categoriesFor(type){return [...new Set((state.category_catalog||state.schema.taxonomy||[]).filter(row=>row.type===type&&row.active).map(row=>row.category).concat('Uncategorized'))].sort();}
function subsFor(type,category){return ['',...new Set((state.category_catalog||state.schema.taxonomy||[]).filter(row=>row.type===type&&row.category===category&&row.active).map(row=>row.subcategory).filter(Boolean))].sort();}
function customForm(row={},prefix='entry'){const values=typeof row.custom_fields==='string'?JSON.parse(row.custom_fields||'{}'):row.custom_fields||{};return state.schema.fields.filter(f=>f.included&&f.key.startsWith('custom_')).map(f=>f.type==='Boolean'?`<label class="check"><input type="checkbox" name="${E(f.key)}" ${values[f.key]===true?'checked':''}>${E(f.label)}</label>`:field(f.label,f.key,values[f.key]||'',f.type==='Date'?'date':'text',{id:prefix+'_'+f.key,hint:f.type==='Number'?'Decimal number saved as exact text':undefined})).join('');}
function recordForm(row={},editing=false,prefix='entry'){const enabled=k=>state.schema.fields.find(f=>f.key===k)?.included!==false;const label=k=>state.schema.fields.find(f=>f.key===k)?.label||k;const type=row.type||'expense',category=row.category||'Uncategorized';return `<div class="form-grid">${field(label('date'),'date',row.date||state.today,'date',{required:true,id:prefix+'_date'})}${select(label('type'),'type',['expense','income','transfer'],type,{id:prefix+'_type'})}${field(label('amount'),'amount',row.amount||'','text',{required:true,id:prefix+'_amount',hint:'Use a negative expense amount for a refund.'})}${field(label('currency'),'currency',row.currency||scope.currency||'','text',{required:true,id:prefix+'_currency',readOnly:true,hint:row.currency?'Recorded currency. Existing amounts are never converted.':'Set currency once in the page header.'})}${enabled('merchant')?field(label('merchant'),'merchant',row.merchant||'','text',{id:prefix+'_merchant',suggest:true,hint:'Leave an absent income source blank.'}):''}${enabled('account')?field(label('account'),'account',row.account||'Unspecified account','text',{required:true,id:prefix+'_account',suggest:true}):''}${enabled('description')?field(label('description'),'description',row.description||'','text',{full:true,id:prefix+'_description',suggest:true,hint:'Suggestions use your confirmed history. Choose a suggestion to apply it.'}):''}${enabled('category')?select(label('category'),'category',[...new Set([...categoriesFor(type),category])],category,{id:prefix+'_category'}):''}${enabled('subcategory')?field(label('subcategory'),'subcategory',row.subcategory||'','text',{id:prefix+'_subcategory',hint:'Choose a shared subcategory, or review a new one before saving.'}):''}${customForm(row,prefix)}</div>${!editing?`<details><summary>Split one expense into two categories</summary><div class="detail-body form-grid"><label class="check full"><input type="checkbox" name="split">Enable a two-way expense split</label>${field('Amount allocated to second category','split_amount','0')}${select('Second category','split_category',categoriesFor('expense'),'Uncategorized')}${select('Second subcategory','split_subcategory',subsFor('expense','Uncategorized'),'')}</div><p class="field-hint">The server calculates the remainder. Splits require a positive expense and cannot split a refund.</p></details>`:''}`;}
function recordValues(form,old={}){const data=new FormData(form);const values=Object.fromEntries(data);const customs=typeof old.custom_fields==='string'?JSON.parse(old.custom_fields||'{}'):structuredClone(old.custom_fields||{});for(const f of state.schema.fields.filter(f=>f.included&&f.key.startsWith('custom_')))customs[f.key]=f.type==='Boolean'?data.has(f.key):data.get(f.key)||'';return {...old,...values,account:values.account||old.account||'Unspecified account',category:values.category||old.category||'Uncategorized',merchant:values.merchant??old.merchant??'',description:values.description??old.description??'',subcategory:values.subcategory??old.subcategory??'',custom_fields:customs};}
function bindCategoryForm(form){const type=$('[name=type]',form),cat=$('[name=category]',form),sub=$('[name=subcategory]',form);const replace=(node,opts,value)=>{if(!node)return;if(node.tagName==='SELECT')node.innerHTML=opts.map(o=>`<option ${o===value?'selected':''}>${E(o)}</option>`).join('');else{let list=document.getElementById(node.id+'-choices');if(!list){list=document.createElement('datalist');list.id=node.id+'-choices';node.after(list);node.setAttribute('list',list.id);}list.innerHTML=opts.map(o=>`<option value="${E(o)}"></option>`).join('');}};replace(sub,subsFor(type?.value||'expense',cat?.value||'Uncategorized'),sub?.value);if(cat?.tagName==='INPUT')replace(cat,categoriesFor(type?.value||'expense'),cat.value);type?.addEventListener('change',()=>{replace(cat,categoriesFor(type.value),'Uncategorized');if(sub)sub.value='';replace(sub,subsFor(type.value,cat?.value||'Uncategorized'),'');});cat?.addEventListener('change',()=>{if(sub)sub.value='';replace(sub,subsFor(type?.value||'expense',cat.value),'');});$('[name=split_category]',form)?.addEventListener('change',event=>replace($('[name=split_subcategory]',form),subsFor('expense',event.target.value),''));bindEntrySuggestions(form,state.transactions);}
function entryPage(){return head('Capture what happened.','Enter one transaction or describe it, then review the exact details and confirm to save.')+`<section class="card" style="max-width:900px"><div class="tabs" role="tablist" aria-label="Entry method"><button role="tab" id="form-tab" aria-selected="true">Transaction form</button><button role="tab" id="sentence-tab" aria-selected="false">Describe it</button></div><form id="entry-form">${recordForm()}<div class="actions" style="margin-top:24px"><button class="primary">Review transaction${icon('arrow')}</button></div></form><form id="sentence-form" hidden><label for="sentence">Describe one transaction</label><textarea id="sentence" name="sentence" required placeholder="I spent 45 ${E(scope.currency)} at a shop yesterday"></textarea><p class="field-hint">Local interpretation. Write today, yesterday or YYYY-MM-DD. You will correct and confirm the details.</p><div class="actions" style="margin-top:20px"><button class="primary">Interpret & review</button></div></form></section>`;}
function setupPage(){const revisit=state.setup_complete;return `<div class="welcome-heading"><p class="eyebrow">A workspace that fits your household</p><h1 tabindex="-1">Make money feel clearer.</h1><p>Bring your data, or describe what matters. We’ll suggest fields you can shape and confirm.</p></div><section class="card setup-card">${revisit?'<div class="notice">Revisiting fields preserves all confirmed records. Removing a custom field keeps its existing values.</div><button type="button" id="edit-current-schema">Edit current fields and shared categories</button>':''}<div class="tabs" role="tablist" aria-label="Start your workspace"><button id="upload-tab" role="tab" aria-selected="true">${icon('import')}Upload a file</button><button id="describe-tab" role="tab" aria-selected="false">${icon('coach')}Describe your fields</button></div><div id="upload-path"><div class="file-drop">${icon('import')}<h2>A little history is enough</h2><p class="muted">Full history, recent records or a sample · CSV, TSV or XLSX · 10 MB</p><label for="setup-file">Choose household transactions</label><input id="setup-file" type="file" accept=".csv,.tsv,.xlsx"></div><details><summary>Templates & entirely fictional demos</summary><div class="detail-body actions"><a class="button" href="/samples/homeaccounts-template.csv" download>Download blank CSV template</a><button id="setup-demo">Try fictional household demo</button><a class="button" href="/samples/household_demo.csv" download>Download household demo</a><a class="button" href="/samples/balances_wishlist_demo.csv" download>Download balances & wishes</a></div><p class="field-hint">The second file contains snapshots and wishes, not transaction history. It cannot be imported as income or expense.</p></details></div><form id="describe-path" hidden><label for="field-description">What would you like to track?</label><textarea id="field-description" required placeholder="date, category, particulars, expense amount, income amount, monthly budget, payment method"></textarea><label class="check"><input id="fields-ai" type="checkbox" ${state.ai.configured?'':'disabled'}>Use optional ${E(state.ai.provider||'OpenAI')} field suggestions</label><p class="field-hint">Default is local rules. If enabled, only this description is sent to ${E(state.ai.provider||'OpenAI')} at ${E(state.ai.base_url||'https://api.openai.com/v1')}; API charges may apply. Key: ${state.ai.configured?'available':'not configured'}. Uploaded files stay local.</p><button class="primary" style="margin-top:15px">Suggest fields</button></form><div id="schema-proposal">${setupDraft?schemaEditor():''}</div></section>${revisit?`<div class="actions" style="justify-content:center;margin-top:20px">${link('Return to workspace','/'+state.settings.home)}</div>`:''}`;}
function schemaEditor(){const fields=setupDraft.fields,guess=state.setup_complete?scope.currency:setupDraft.currency||state.settings.currency||'';return `<hr style="border:0;border-top:1px solid var(--border);margin:28px 0"><p class="eyebrow">Review before opening your workspace</p><h2 style="margin:10px 0 14px">Here are the fields I suggest using</h2>${(setupDraft.notes||[]).map(n=>`<p class="notice">${E(n)}</p>`).join('')}<form id="schema-form"><div class="table-wrap"><table><thead><tr><th>Include</th><th>Field name</th><th>Type</th><th>Source / meaning</th><th>Remove</th></tr></thead><tbody>${fields.map((f,i)=>`<tr data-schema-row="${i}"><td><label class="check"><input type="checkbox" name="included" ${f.included?'checked':''} ${f.required?'disabled':''}><span>${f.required?'Required':'Optional'}</span></label></td><td><input aria-label="Field ${i+1} name" name="label" value="${E(f.label)}" required></td><td><select aria-label="Field ${i+1} type" name="type" ${f.required||!f.key.startsWith('custom_')?'disabled':''}>${['Text','Number','Date','Boolean'].map(t=>`<option ${t===f.type?'selected':''}>${t}</option>`).join('')}</select></td><td><input aria-label="Field ${i+1} source" name="source" value="${E(f.source)}"></td><td>${f.required?'—':`<button type="button" data-remove-field="${i}" aria-label="Remove field ${E(f.label)}">${icon('close')}</button>`}</td></tr>`).join('')}</tbody></table></div><button type="button" id="add-custom-field" style="margin-top:14px">${icon('entry')}Add custom field</button><div class="form-grid" style="margin-top:22px">${state.setup_complete?field('Currency','setup_currency',guess,'text',{required:true,readOnly:true,hint:'Set currency in the page header.'}):select('Default currency (required)','setup_currency',[{value:'',label:'Choose currency'},...state.currencies.map(c=>({value:c.code,label:c.label}))],guess,{required:true})}</div>${setupDraft.currency?`<p class="field-hint">Suggested ${E(setupDraft.currency)} from file rows. Existing row currencies are preserved.</p>`:''}<p class="field-hint">Date, type, amount and currency support deterministic reports. Custom fields appear in entry, edits, lists and exports; they do not create new calculations.</p><details><summary>Optional household category suggestions</summary><div class="detail-body"><label class="check"><input id="apply-taxonomy" type="checkbox" ${(setupDraft.applyTaxonomy??Boolean((state.schema.taxonomy||[]).length))?'checked':''}>Apply this editable list to new entries</label><p class="field-hint">Suggestions, not a universal standard. Referenced removals are archived; existing classifications and records are preserved.</p><div id="taxonomy-editor">${taxonomyEditor(state.setup_complete&&state.category_catalog?.length?state.category_catalog:state.starter_taxonomy)}</div></div></details><div class="actions" style="margin-top:24px"><button class="primary" id="confirm-fields">Confirm fields & continue${icon('arrow')}</button><button type="button" id="discard-schema">Back to starting options</button></div><p class="field-hint" id="schema-ready">${guess?'Your fields and currency are ready for confirmation.':'Choose a default currency to enable confirmation.'}</p></form>`;}
function taxonomyEditor(tax){taxDraft=structuredClone(tax);return `<div class="table-wrap" style="margin-top:14px"><table><thead><tr><th>Type</th><th>Category</th><th>Subcategory</th><th>Active</th><th>Remove</th></tr></thead><tbody>${taxDraft.map((r,i)=>`<tr data-tax-row="${i}"><td><select name="type" aria-label="Category ${i+1} type">${['income','expense','transfer'].map(t=>`<option ${t===r.type?'selected':''}>${t}</option>`).join('')}</select></td><td><input name="category" aria-label="Category ${i+1} name" value="${E(r.category)}"></td><td><input name="subcategory" aria-label="Category ${i+1} subcategory" value="${E(r.subcategory)}"></td><td><input type="checkbox" name="active" aria-label="Category ${i+1} active" ${r.active?'checked':''}></td><td><button type="button" data-remove-tax="${i}" aria-label="Remove category row ${i+1}">${icon('close')}</button></td></tr>`).join('')}</tbody></table></div><button type="button" id="add-category" style="margin-top:12px">Add category</button>`;}
function captureSchema(){if(!$('#schema-form'))return;setupDraft.fields=$$('[data-schema-row]').map(tr=>{const old=setupDraft.fields[Number(tr.dataset.schemaRow)];return {...old,label:$('[name=label]',tr).value,type:$('[name=type]',tr).value,source:$('[name=source]',tr).value,included:old.required||$('[name=included]',tr).checked};});setupDraft.currency=$('[name=setup_currency]').value;setupDraft.applyTaxonomy=$('#apply-taxonomy').checked;captureTax();}
function captureTax(){taxDraft=$$('[data-tax-row]').map(tr=>({type:$('[name=type]',tr).value,category:$('[name=category]',tr).value,subcategory:$('[name=subcategory]',tr).value,active:$('[name=active]',tr).checked}));}
function importPage(){return head('Bring the pieces together.','Upload and map locally. Confirm fields first; confirm records separately.')+`<section class="card"><div class="actions" style="margin-bottom:20px"><label class="button">${icon('import')}Choose CSV / TSV / XLSX<input id="import-file" type="file" accept=".csv,.tsv,.xlsx" style="position:absolute;width:1px;height:1px;min-height:0;opacity:0"></label><button id="import-demo">Try small fictional demo</button><button id="import-us-transactions">US demo: 462 transactions</button><button id="import-us-budgets">US demo: 324 budgets</button><button id="import-snapshot">Inspect fictional balances & wishes</button>${link('Review field setup','/setup')}</div><p class="field-hint">The US demo covers November 2025 to October 2026 in USD. Import its transactions, then its matching budgets; each needs your confirmation. Nothing is imported automatically. Snapshots, account balances and wishes are never treated as transactions.</p><div id="import-body">${fileDraft?importMapping():''}</div></section>`;}
function mappingGuess(field,headers){const aliases={date:['date','தேதி'],merchant:['merchant','source','விவரம்'],description:['particulars','description','notes'],category:['category'],subcategory:['subcategory','sub category'],expense:['expense amount','expense','செலவு'],income:['income amount','income','வரவு'],amount:['amount'],type:['type','transaction type'],currency:['currency'],account:['account'],period:['period','budget period'],budget:['monthly budget','amount alloted','budget','amount']};const source=state.schema.fields.find(f=>f.key===field)?.source;return headers.includes(source)?source:headers.find(h=>(aliases[field]||[]).includes(h.trim().toLowerCase().replaceAll('_',' ')))||'';}
async function chooseDemo(filename,kind){fileDraft=await api('/api/demo',{filename});selectedSheet=fileDraft.selected;importKind=kind;const url=new URL(location.href);url.searchParams.set('kind',kind);history.replaceState(history.state,'',url.pathname+url.search);$('#import-body').innerHTML=importMapping();const form=$('#import-mapping');$('[name=currency]',form).value='USD';if(kind==='Budgets')$('[name=map_budget]',form).value='amount';bindImport();}
function importMapping(){const f=fileDraft;const headers=f.headers;selectedSheet=selectedSheet||f.selected;const kind=new URLSearchParams(location.search).get('kind')||importKind;importKind=kind;const fields=kind==='Budgets'?['period','category','subcategory','budget','currency']:['date','merchant','description','category','subcategory','expense','income','amount','type','currency','account',...state.schema.fields.filter(f=>f.included&&f.key.startsWith('custom_')).map(f=>f.key)];return `<div class="subheading"><h2>${E(f.filename)}</h2><p class="field-hint">Map amounts + type, or separate expense/income columns. Missing currency uses your chosen default.</p></div><form id="import-mapping"><div class="form-grid three">${select('Import as','kind',['Transactions','Budgets'],kind)}${select('Sheet to review','sheet',f.sheets,selectedSheet)}${field('Default currency','currency',scope.currency||'','text',{required:true,readOnly:true,hint:'Set in the page header. File rows keep their original currency.'})}${field('Default account','account','Unspecified account')}${field('Budget year for month-named sheets','year',state.today.slice(0,4),'number')}${select('Text date format','date_style',['ISO (YYYY-MM-DD)','US (MM/DD/YYYY)','Day first (DD/MM/YYYY)'],'ISO (YYYY-MM-DD)')}</div><details open><summary>Confirm field mapping</summary><div class="detail-body form-grid three">${fields.map(k=>select(state.schema.fields.find(f=>f.key===k)?.label||k.replaceAll('_',' '),'map_'+k,[{value:'',label:'Not mapped'},...headers],mappingGuess(k,headers)||state.schema.fields.find(f=>f.key===k)?.source||'')).join('')}</div></details><details><summary>Source sample</summary><div class="table-wrap detail-body"><table><thead><tr>${headers.map(h=>`<th>${E(h)}</th>`).join('')}</tr></thead><tbody>${f.sample.map(r=>`<tr>${r.map(v=>`<td>${E(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details><button class="primary" style="margin-top:20px">Prepare import review${icon('arrow')}</button></form><div id="import-preview"></div>`;}
function importPreviewHTML(result){return `<div class="subheading"><h2>Review the normalized records</h2></div><p class="notice">${result.transactions.length} new transactions · ${result.budgets.length} new monthly budgets · ${result.skipped} template/total rows skipped · ${result.repeated} previously imported rows skipped</p>${result.issues.length?`<p class="notice error">Import is blocked until invalid rows are corrected.</p><ul>${result.issues.map(i=>`<li>${E(i.error)} · row ${E(i.row)}</li>`).join('')}</ul>`:''}${result.conflicts.length?'<p class="notice error">Conflicting budgets already exist for the same month/category/currency. Adjust them in Budgets or correct the source.</p>':''}${result.possible_duplicates.length?'<p class="notice">Possible duplicates require acknowledgement in the final confirmation. They may be genuine repeated transactions.</p>':''}${recordTable(result.transactions)}${importAllRows.length?`<details><summary>Exclude records from this import · optional</summary><div class="detail-body">${importAllRows.map(row=>`<label class="check"><input type="checkbox" class="exclude-import" value="${E(row.id)}" ${importExclusions.includes(row.id)?'checked':''}>${E(row.date)} · ${E(row.merchant||row.description)} · ${E(row.amount)} ${row.currency}</label>`).join('')}<button id="apply-exclusions" style="margin-top:14px">Update import preview</button></div></details>`:''}${result.budgets.length?`<div class="table-wrap"><table><thead><tr><th>Month</th><th>Category</th><th>Subcategory</th><th>Budget</th><th>Currency</th></tr></thead><tbody>${result.budgets.map(b=>`<tr><td>${E(b.period)}</td><td>${E(b.category)}</td><td>${E(b.subcategory)}</td><td>${E(b.amount)}</td><td>${b.currency}</td></tr>`).join('')}</tbody></table></div>`:''}${result.review?'<button class="primary" id="stage-import" style="margin-top:20px">Continue to confirmation</button>':''}`;}
function settingsPage(){return head('Make this space yours.','Choose your visual mode and home screen, manage shared categories, or review undo for the last financial change.')+`<section class="grid two"><article class="card"><h2>Visual mode</h2><p class="field-hint">Three distinct, accessible palettes. Your choice stays on this computer.</p><div class="segmented" style="margin:24px 0">${['light','dark','bright'].map(t=>`<button class="theme-choice" data-theme-choice="${t}" aria-pressed="${state.settings.theme===t}"><span class="swatch"></span>${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><form id="home-form">${select('Your home screen','home',[{value:'overview',label:'Overview · conventional menu home'},{value:'coach',label:'Coach · chat-first home'}],state.settings.home)}<button class="primary" style="margin-top:18px">Save home preference</button></form><p class="field-hint">Opening / uses your chosen home. All menu routes remain available.</p></article><article class="card"><h2>Your data, kept local</h2><p class="muted" style="margin-top:12px">Records use the same CSV revision store and remain reversible with undo. Field setup and visual preferences are separate settings.</p><div class="actions" style="margin-top:20px">${link('Review fields & categories','/setup')}<button id="undo-review" ${state.history.length?'':'disabled'}>${icon('undo')}Review undo</button></div><details><summary>Optional connected AI</summary><div class="detail-body">${state.ai.error?`<p class="notice error">${E(state.ai.error)}</p>`:''}<p>Key: ${state.ai.configured?'available on this computer':'not configured'} · Model: ${E(state.ai.model)}</p><p class="field-hint">OpenAI is off until enabled in Coach or field setup. Coach sends the disclosed question, recent chat, verified totals, hierarchy and up to 50 scoped records. Charges may apply. Keys stay server-side. Dictation and Voice conversation have separate opt-ins before sending microphone audio to OpenAI.</p><p class="field-hint">OpenAI API credits are separate from a ChatGPT subscription. If credits run out, local typed chat remains available.</p></div></details></article></section>`;}
function coachPage(drawer=false){return renderCoachUI({E,icon,link,state,scope,chat,chatDraft,useAI,drawer,settingsOpen:chatSettingsOpen,pending:chatPending,...speech.settings});}
const resources=[['Investor.gov · Compound interest','https://www.investor.gov/financial-tools-calculators/calculators/compound-interest-calculator'],['Fidelity · Withdrawal-rate assumptions','https://www.fidelity.com/viewpoints/retirement/how-long-will-savings-last'],['Morningstar · Personal finance','https://www.morningstar.com/personal-finance'],['NerdWallet · How compounding works','https://www.nerdwallet.com/banking/learn/what-is-compound-interest'],['The Millionaire Next Door · Publisher details','https://www.simonandschuster.net/books/The-Millionaire-Next-Door/Thomas-J-Stanley/9781630762506'],['Moneychimp · Calculator inspiration','https://www.moneychimp.com/calculator/compound_interest_calculator.htm']];
function learnPage(){return head('A little knowledge compounds.','Understand a concept, then make a decision in your own context.')+`<section class="grid two"><article class="card"><h2>Start with the distinctions</h2><div class="row"><div><h3>Surplus is a record, not a transfer</h3><p class="field-hint">Income minus net expenses does not prove money was saved or invested. Enter verified contributions separately in planning.</p></div></div><div class="row"><div><h3>Compound growth is an assumption</h3><p class="field-hint">Prior growth becomes part of what grows next. Fixed rates omit taxes, fees and market variability.</p></div></div><div class="row"><div><h3>A FIRE target is adjustable</h3><p class="field-hint">Annual expenses divided by a chosen withdrawal rate. At 4%, it is 25× expenses. It is not a guarantee or a recommendation to stop working.</p></div></div><p class="field-hint">Book: The Millionaire Next Door, by Thomas J. Stanley and William D. Danko. Resources are for learning, not product endorsements.</p></article><article class="card"><h2 style="margin-bottom:18px">Read at your pace</h2><div class="learning">${resources.map(([name,href])=>`<a class="external" href="${href}" target="_blank" rel="noopener noreferrer">${E(name)}${icon('arrow')}</a>`).join('')}</div></article></section>`;}
function planningPage(){const tab=new URLSearchParams(location.search).get('tab')||'goals';const tabs=[['goals','Savings goals'],['fire','FIRE scenario'],['growth','Compound growth'],['variance','Budget variance']];const form={goals:()=>`${field('Goal name','name','','text',{full:true,placeholder:'Emergency fund, a home, a course…'})}${field('Goal amount','target','0')}${field('Cash already saved toward this goal','saved','0')}${field('Goal horizon in months','months','12','number',{min:1})}${field('Desired share of recorded income (%)','percent','20','number',{min:0})}`,fire:()=>`${field('Expected annual expenses · today’s money','annual_expenses','0')}${field('Chosen withdrawal rate (%)','withdrawal_rate','4')}${field('Current invested portfolio assets','portfolio','0')}${field('Planned contribution per chosen period','contribution','0')}${select('Contribution frequency','frequency',['Monthly','Annual'],'Monthly')}${field('Planning horizon in years','years','10','number',{min:0})}${field('Assumed annual return (%)','annual_rate','5')}${field('Assumed annual inflation (%)','inflation','2')}${field('Optional second return assumption (%)','other_return','')}`,growth:()=>`${field('Principal','principal','1000')}${field('Contribution per chosen period','contribution','100')}${select('Contribution frequency','frequency',['Annual','Monthly'],'Annual')}${select('Contribution timing','timing',['End','Beginning'],'End')}${field('Years','years','10','number',{min:0})}${field('Nominal annual rate (%)','annual_rate','5')}${field('Compounding periods per year','periods','1','number',{min:1})}${field('Inflation for today’s-money view (%)','inflation','2')}`,variance:()=>`${field('Planned budget','budget','300')}${field('Actual spending · net of refunds','actual','315')}`};return head('Give tomorrow some thought.','Transparent scenarios, separate from confirmed transactions.')+`<p class="notice">Recorded surplus is ${E(report.surplus.display)}. It is not automatically saved or invested. Calculators use your assumptions and do not change records or budgets.</p><section class="card"><div class="tabs" aria-label="Planning calculators">${tabs.map(([key,title])=>`<a href="/planning?tab=${key}" data-route ${tab===key?'aria-current="page"':''}>${title}</a>`).join('')}</div>${tab==='fire'?`<details><summary>Use an observed expense estimate</summary><div class="detail-body form-grid">${select('Observed year','observed_year',[...new Set(state.transactions.filter(t=>t.currency===scope.currency).map(t=>t.date.slice(0,4)))].sort().reverse().concat(state.today.slice(0,4)).filter((y,i,a)=>a.indexOf(y)===i),scope.month.slice(0,4))}${field('Also exclude transfer-like categories · comma separated','exclude_categories','ATM Withdrawal')}<button type="button" id="observed-estimate">Use observed annual estimate</button><p class="field-hint full" id="observed-note">Incomplete months can distort an estimate. Review and override it. Transfers and refunds are handled separately.</p></div></details>`:''}<form id="planning-form" data-kind="${E(tab)}"><h2 style="margin:20px 0">${tabs.find(t=>t[0]===tab)?.[1]||'Savings goals'} · ${E(scope.currency)}</h2><div class="form-grid">${(form[tab]||form.goals)()}</div><button class="primary" style="margin-top:22px">Calculate scenario${icon('arrow')}</button></form><details><summary>Verified invested contribution · optional</summary><div class="detail-body">${field('Amount you actually invested this month','verified_invested','')}<p class="field-hint" id="verified-note">This input stays in this page session. It does not create a transaction and is not inferred from salary, balances or surplus.</p></div></details><div id="planning-results"></div><p class="footnote">Currency: ${scope.currency}. No exchange conversion. Growth assumes a fixed rate, chosen compounding and deposit timing; no taxes, fees or variable returns. FIRE target = annual expenses ÷ withdrawal rate. Goal gaps are before interest. Variance = actual − budget; percentage divides by budget and is undefined for zero.</p></section>`;}
function growthChart(rows){const max=Math.max(1,...rows.map(r=>r['Projected value']));const points=rows.map((r,i)=>`${30+i/(rows.length-1||1)*700},${240-r['Projected value']/max*210}`).join(' ');return `<svg class="linechart" role="img" aria-label="Projected value under the chosen fixed-rate assumptions" viewBox="0 0 760 280"><path d="M30 20V240H730" stroke="var(--border)" fill="none"/><polyline points="${points}" fill="none" stroke="var(--chart)" stroke-width="3"/><text x="30" y="268" fill="var(--muted)" font-size="12">Year 0</text><text x="680" y="268" fill="var(--muted)" font-size="12">Year ${rows.at(-1).Year}</text></svg>`;}
function planningResults(kind,result){if(kind==='variance')return `<div class="calc-results grid stats">${metric(result.label,money(Math.abs(result.difference)),result.percent===null?'Percentage undefined for a zero budget':result.percent.toFixed(2)+'% · (actual − budget) / budget')}${metric('Effect on your data','None','This comparison does not save a budget')}</div>`;if(kind==='goals')return `<div class="calc-results grid stats">${metric('Goal remaining',scope.currency+' '+result.remaining,'Goal amount − cash saved')}${metric('Monthly gap',money(result.monthly),'Before interest, over chosen months')}${metric('Planned income allocation',money(result.allocation),'Plan, not evidence of a contribution')}${metric('Cash goal progress',result.progress.toFixed(1)+'%','Separate from portfolio assets')}</div>`;const end=result.rows.at(-1);return `<div class="calc-results grid stats">${kind==='fire'?metric('Illustrative target today',money(result.target),result.multiple.toFixed(2)+'× annual expenses'):metric('Projected future value',money(end['Projected value']),'Fixed-rate scenario, not a promise')}${kind==='fire'?metric('Portfolio progress',result.progress===null?'Enter annual expenses':result.progress.toFixed(1)+'%','Current invested assets / target'):metric('Principal + contributions',money(end.Contributions),'Deposits under your assumptions')}${metric('Modeled growth / loss',money(end.Growth),'Projected value − contributions')}${metric('In today’s money',money(end['Inflation-adjusted value']),'Adjusted by chosen inflation')}</div>${kind==='fire'?`<p class="notice">Horizon nominal portfolio: ${money(end['Projected value'])}. Inflated horizon target: ${money(result.horizon_target)}. End-of-period contributions and annual compounding.</p>`:''}${growthChart(result.rows)}<div class="table-wrap"><table><thead><tr><th>Year</th><th>Contributions</th><th>Growth</th><th>Projected value</th><th>Today’s-money value</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${r.Year}</td><td>${E(money(r.Contributions))}</td><td>${E(money(r.Growth))}</td><td>${E(money(r['Projected value']))}</td><td>${E(money(r['Inflation-adjusted value']))}</td></tr>`).join('')}</tbody></table></div>${result.comparison?`<p class="notice" style="margin-top:20px">Second assumption: ${result.comparison.rate}% return → nominal portfolio ${money(result.comparison.value)}. Same contributions, inflation and horizon.</p>`:''}`;}
function summaryRows(rows){return rows.map(r=>`<div class="review-record"><div class="review-summary">${Object.entries(r).filter(([k])=>!['source_ref','custom_fields'].includes(k)).map(([k,v])=>`<div ${k==='id'?'data-record-id':''}><small>${E(k)}</small>${E(v)}</div>`).join('')}${r.custom_fields?Object.entries(typeof r.custom_fields==='string'?JSON.parse(r.custom_fields||'{}'):r.custom_fields).map(([k,v])=>`<div><small>${E(state.schema.fields.find(f=>f.key===k)?.label||k)}</small>${E(v)}</div>`).join(''):''}</div></div>`).join('');}
function clearNotice(proposal){return proposal.kind==='clear'?`<div class="notice error"><h3>Clear all ${proposal.clear_count} transactions?</h3><p>This includes every month and currency, beyond the current filters. Budgets, fields, preferences and undo history are kept. Import tracking is reset so the same file can be imported again.</p><p>Undo can restore these transactions. This does not permanently erase historical files.</p></div><label class="check"><input type="checkbox" id="confirm-clear">I understand this clears all transactions across every month and currency.</label>`:'';}
function openReview(review){pending=review;const p=review.proposal;const dialog=$('#review');dialog.innerHTML=`<div class="dialog-head"><div><p class="eyebrow">Nothing has been saved</p><h2 id="review-title">Review before saving</h2></div><button id="close-review" class="subtle" aria-label="Close review">${icon('close')}</button></div><div class="dialog-body"><div id="review-error" class="notice error" role="alert" hidden></div><p class="notice">${p.kind==='undo'?'Undo restores both financial CSVs to the previous revision. Field and visual settings are separate.':'Check the exact records and the locally calculated effect. Budgets will not increase automatically.'}</p>${clearNotice(p)}${review.category_additions?.length?`<div class="notice"><h3>New shared categories</h3><p>These exact classifications will become available to transactions and budgets.</p><ul>${review.category_additions.map(row=>`<li>${E(row.type)} · ${E(row.category)}${row.subcategory?' / '+E(row.subcategory):''}</li>`).join('')}</ul></div><label class="check"><input type="checkbox" id="accept-categories">I reviewed and want to add these shared categories.</label>`:''}${p.before?.length?`<h3>Current record${p.before.length>1?'s':''}</h3>${summaryRows(p.before)}`:''}${p.rows?.length?`<h3>${p.kind==='delete'?'Records to remove':p.kind==='undo'?'Records restored by undo':'Proposed records'}</h3>${summaryRows(p.rows)}`:''}${p.kind==='delete'?'<p class="notice error">This exact current record will be removed. Undo remains available.</p>':''}${p.budget_before?.length?`<h3>Current monthly budgets before undo</h3>${summaryRows(p.budget_before)}`:''}${p.budgets?.length?`<h3>Proposed monthly budgets</h3>${summaryRows(p.budgets)}`:''}${p.undo_counts?`<p class="notice">Transactions: ${p.undo_counts.current_transactions} → ${p.undo_counts.restored_transactions}. Monthly budgets: ${p.undo_counts.current_budgets} → ${p.undo_counts.restored_budgets}. Current changed records are shown above; proposed records restore the prior version.</p>`:''}${review.effects.length?`<h3 class="subheading">Budget impact</h3>${review.effects.map(b=>`<p class="notice">${E(b.category)}${b.subcategory?' / '+E(b.subcategory):''} · ${b.currency}: current ${b.current} → proposed ${b.proposed_total}, limit ${b.budget}; over budget ${b.over_budget}.</p>`).join('')}`:''}${review.changes?.length?`<h3 class="subheading">Overall monthly effect</h3>${review.changes.map(c=>`<p class="notice">${E(c.month)} · ${c.currency}: expenses ${c.current_expenses} → ${c.proposed_expenses}; income ${c.current_income} → ${c.proposed_income}; planned budget ${c.current_budget} → ${c.proposed_budget}.</p>`).join('')}`:''}${['add','edit','budget'].includes(p.kind)?`<details><summary>Correct the proposed details</summary><form class="detail-body" id="correct-proposal">${p.rows.map((r,i)=>`<div class="review-record"><div data-correct-row="${i}">${p.kind==='budget'?budgetForm(r,'correct_'+i):recordForm(r,true,'correct_'+i)}</div></div>`).join('')}<button>Update preview</button></form></details>`:''}${review.duplicates.length?'<label class="check"><input type="checkbox" id="accept-duplicates">I reviewed possible duplicates and want to keep these records.</label>':''}${review.uncategorized?'<label class="check"><input type="checkbox" id="accept-uncategorized">I reviewed uncategorized records and will keep them for now.</label>':''}</div><div class="dialog-actions"><button id="cancel-review">Keep reviewing</button><button class="${p.kind==='clear'?'danger':'primary'}" id="confirm-save" ${p.kind==='clear'?'disabled':''}>${icon('check')}${p.kind==='undo'?'Confirm undo':p.kind==='clear'?'Confirm clear all transactions':'Confirm save'}</button></div>`;if(!dialog.open)dialog.showModal();$('#close-review').onclick=()=>dialog.close();$('#cancel-review').onclick=()=>dialog.close();$('#confirm-save').onclick=()=>action(async()=>{try{const previousIds=new Set(state.transactions.map(row=>row.id));const result=await api('/api/proposal/confirm',{token:pending.token,accept_duplicates:$('#accept-duplicates')?.checked||false,accept_uncategorized:$('#accept-uncategorized')?.checked||false,confirm_clear:$('#confirm-clear')?.checked===true,accept_categories:$('#accept-categories')?.checked===true});dialog.close();$('#entry-dialog').close();pending=null;await refresh();newRecordIds=new Set(state.transactions.filter(row=>!previousIds.has(row.id)).map(row=>row.id));await render();toast(result.message);}catch(error){$('#review-error').hidden=false;$('#review-error').textContent=error.message;}},$('#confirm-save'));$('#confirm-clear')?.addEventListener('change',event=>$('#confirm-save').disabled=!event.target.checked);$('#correct-proposal')?.addEventListener('submit',event=>{event.preventDefault();action(async()=>{const rows=$$('[data-correct-row]').map((node,i)=>{const values={};$$('input,select',node).forEach(el=>{values[el.name]=el.type==='checkbox'?el.checked:el.value;});const original=p.rows[i];const custom=typeof original.custom_fields==='string'?JSON.parse(original.custom_fields||'{}'):original.custom_fields||{};for(const f of state.schema.fields.filter(f=>f.included&&f.key.startsWith('custom_')))custom[f.key]=values[f.key]??custom[f.key];return {...original,...values,custom_fields:custom};});const previousToken=pending.token;const updated=await api('/api/proposal/correct',{token:previousToken,rows});for(const message of chat)if(message.review?.token===previousToken)message.review=updated;openReview(updated);},event.submitter);});$$('[data-correct-row]').forEach(bindCategoryForm);}
function budgetForm(row={},prefix='budget'){return `<div class="form-grid">${field('Month (YYYY-MM)','period',row.period||scope.month,'month',{required:true,id:prefix+'_period'})}${field('Currency','currency',row.currency||scope.currency,'text',{required:true,id:prefix+'_currency',readOnly:true,hint:row.currency?'Recorded currency. Existing amounts are never converted.':'Set currency once in the page header.'})}${field('Category','category',row.category||'','text',{required:true,id:prefix+'_category'})}${field('Subcategory · blank = entire category','subcategory',row.subcategory||'','text',{id:prefix+'_subcategory'})}${field('Planned budget amount','amount',row.amount||'','text',{required:true,id:prefix+'_amount'})}</div>`;}
function openBudget(row={}){const dialog=$('#review');dialog.innerHTML=`<div class="dialog-head"><h2 id="review-title">Set an intentional limit</h2><button id="close-review" class="subtle" aria-label="Close budget form">${icon('close')}</button></div><div class="dialog-body"><p class="notice">This form prepares a preview. Saving requires your next confirmation.</p><form id="budget-form">${budgetForm(row)}<button class="primary" style="margin-top:20px">Review budget</button></form></div>`;dialog.showModal();$('#close-review').onclick=()=>dialog.close();bindCategoryForm($('#budget-form'));$('#budget-form').onsubmit=event=>{event.preventDefault();action(async()=>openReview(await api('/api/proposal',{kind:'budget',rows:[Object.fromEntries(new FormData(event.target))]})),event.submitter);};}
function openEdit(id){const old=state.transactions.find(t=>t.id===id);if(!old)return toast('Record not found. Refresh the page.');const dialog=$('#review');dialog.innerHTML=`<div class="dialog-head"><h2 id="review-title">Review a record</h2><button id="close-review" class="subtle" aria-label="Close record editor">${icon('close')}</button></div><div class="dialog-body"><p class="notice">Record ${E(old.id)}. Nothing changes until a corrected preview is confirmed.</p><form id="edit-form">${recordForm(old,true,'edit')}<button class="primary" style="margin-top:20px">Review changes</button></form></div>`;dialog.showModal();$('#close-review').onclick=()=>dialog.close();bindCategoryForm($('#edit-form'));$('#edit-form').onsubmit=event=>{event.preventDefault();action(async()=>openReview(await api('/api/proposal',{kind:'edit',id,rows:[recordValues(event.target,old)]})),event.submitter);};}
async function uploadFile(file){if(file.size>10000000)throw new Error('Maximum file size is 10 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let start=0;start<bytes.length;start+=32768)binary+=String.fromCharCode(...bytes.subarray(start,start+32768));return api('/api/upload',{filename:file.name,data:btoa(binary)});}
function applyFileProposal(file){fileDraft=file;selectedSheet=file.selected;const index=file.headers.findIndex(h=>h.toLowerCase()==='currency');const found=index>=0?file.sample.map(r=>r[index]).find(c=>state.currencies.some(code=>code.code===c)):null;setupDraft={fields:file.fields,notes:file.notes,currency:found||state.settings.currency||''};}
function showSchema(){const tax=taxDraft.length?structuredClone(taxDraft):null;$('#schema-proposal').innerHTML=schemaEditor();if(tax)$('#taxonomy-editor').innerHTML=taxonomyEditor(tax);bindSchema();}
function bindSchema(){const form=$('#schema-form');if(!form)return;const curr=$('[name=setup_currency]');function ready(){const okay=Boolean(curr.value);$('#confirm-fields').disabled=!okay;$('#schema-ready').textContent=okay?'Your fields and currency are ready for confirmation.':'Choose a default currency to enable confirmation.';}curr.onchange=ready;ready();$('#add-custom-field').onclick=()=>{captureSchema();setupDraft.fields.push({key:'custom_new_'+crypto.randomUUID().slice(0,8),label:'New field',type:'Text',included:true,required:false,source:''});showSchema();};$$('[data-remove-field]').forEach(b=>b.onclick=()=>{captureSchema();setupDraft.fields.splice(Number(b.dataset.removeField),1);showSchema();});function taxEvents(){$$('[data-remove-tax]').forEach(b=>b.onclick=()=>{captureTax();taxDraft.splice(Number(b.dataset.removeTax),1);$('#taxonomy-editor').innerHTML=taxonomyEditor(taxDraft);taxEvents();});$('#add-category').onclick=()=>{captureTax();taxDraft.push({type:'expense',category:'New category',subcategory:'',active:true});$('#taxonomy-editor').innerHTML=taxonomyEditor(taxDraft);taxEvents();};}taxEvents();$('#discard-schema').onclick=()=>{setupDraft=null;$('#schema-proposal').innerHTML='';};form.onsubmit=event=>{event.preventDefault();captureSchema();action(async()=>{const result=await api('/api/setup',{fields:setupDraft.fields,currency:setupDraft.currency,...($('#apply-taxonomy').checked?{taxonomy:taxDraft}:{})});setupDraft=null;scope.currency=null;scope.month=null;await refresh();await go(fileDraft?'/import':'/entry');toast(result.message);},event.submitter);};}
function bindImport(){const form=$('#import-mapping');if(!form)return;$('[name=kind]',form).onchange=event=>{importKind=event.target.value;history.replaceState({},'',`/import?kind=${importKind}`);$('#import-body').innerHTML=importMapping();bindImport();};$('[name=sheet]',form).onchange=event=>action(async()=>{const result=await api('/api/upload/sheet',{file_token:fileDraft.file_token,sheet:event.target.value});fileDraft={...fileDraft,...result};selectedSheet=event.target.value;$('#import-body').innerHTML=importMapping();bindImport();});form.onsubmit=event=>{event.preventDefault();action(async()=>{const data=Object.fromEntries(new FormData(form));const mapping=Object.fromEntries(Object.entries(data).filter(([k])=>k.startsWith('map_')).map(([k,v])=>[k.slice(4),v]));importRequest={file_token:fileDraft.file_token,selected:[data.sheet],mapping,currency:data.currency,account:data.account,year:data.year,date_style:data.date_style,kind:data.kind};importExclusions=[];importResult=await api('/api/import/review',importRequest);importAllRows=importResult.transactions;showImportPreview();},event.submitter);};}
function showImportPreview(){
 $('#import-preview').innerHTML=importPreviewHTML(importResult);
 $('#stage-import')?.addEventListener('click',()=>openReview(importResult.review));
 $$('.exclude-import').forEach(node=>node.onchange=()=>{if($('#stage-import'))$('#stage-import').disabled=true;});
 $('#apply-exclusions')?.addEventListener('click',event=>action(async()=>{importExclusions=$$('.exclude-import').filter(n=>n.checked).map(n=>n.value);importResult=await api('/api/import/review',{...importRequest,exclude:importExclusions});showImportPreview();},event.currentTarget));
}
async function download(kind){const q=new URLSearchParams(location.search);q.set('kind',kind);if(kind==='transactions'){q.set('currency',scope.currency);if(q.get('all')!=='1')q.set('month',scope.month);else q.delete('month');}const response=await fetch('/api/export?'+q);if(!response.ok)throw new Error('Export failed.');const blob=await response.blob();const href=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=href;anchor.download=`homeaccounts-${kind}.csv`;anchor.click();URL.revokeObjectURL(href);}
async function sendChat(text){
 if(chatPending||speech.active||!text.trim()||text.length>6000)return;
 chatPending=true;chatDraft='';chat.push({role:'user',content:text});renderChat();
 try{const result=await api('/api/chat',{text,currency:scope.currency,month:scope.month,reference_date:state.today,use_ai:useAI,provider_endpoint:state.ai.endpoint,history:chat.slice(-7,-1).map(m=>({role:m.role,content:m.content}))});
 chat.push({role:'assistant',content:result.answer,links:result.links,review:result.review});renderChat();speech.readNew(result.answer,chat.length-1);if(result.review)openReview(result.review);
 }catch(error){chat.push({role:'assistant',content:error.message});}
 finally{chatPending=false;renderChat();$('#chat-text')?.focus();}
}
function menuClose(){const sidebar=$('#navigation');sidebar?.classList.remove('open');if($('.workspace'))$('.workspace').inert=false;if($('.bottom-nav'))$('.bottom-nav').inert=false;$('#menu-open')?.setAttribute('aria-expanded','false');}

function newRecordsNotice(){const rows=state.transactions.filter(row=>newRecordIds.has(row.id));return rows.length?`<div class="notice saved-records" role="status"><strong>${rows.length} transaction${rows.length===1?'':'s'} saved.</strong> Newly added records are highlighted when they match your filters. ${link('View saved transaction',`/transactions?${new URLSearchParams({currency:rows[0].currency,month:rows[0].date.slice(0,7),search:rows[0].id})}`,'')}</div>`:'';}
function openEntry(){walkthrough.stop();const dialog=$('#entry-dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="entry-dialog-title">Add transaction</h2><button type="button" id="close-entry" aria-label="Close transaction form">${icon('close')}</button></div><div class="dialog-body">${entryPage()}</div>`;dialog.showModal();$('#close-entry').onclick=()=>dialog.close();bindEntry();}
function openChat(){if(route()==='coach'){$('#chat-text')?.focus();return;}chatDrawerOpen=true;$('#chat-drawer').hidden=false;renderChat();$('#open-chat')?.setAttribute('aria-expanded','true');$('#chat-text')?.focus();}
function closeChat(focus=true){speech.stop();chatDrawerOpen=false;const drawer=$('#chat-drawer');if(drawer){drawer.hidden=true;drawer.replaceChildren();}$('#open-chat')?.setAttribute('aria-expanded','false');if(focus)$('#open-chat')?.focus();}
function renderChat(){const destination=chatDrawerOpen?$('#chat-drawer'):route()==='coach'?$('#page'):null;if(!destination)return;destination.innerHTML=chatDrawerOpen?`<div class="drawer-header"><h2 id="chat-drawer-title">Home Accounts chat</h2><div class="actions"><button id="expand-chat" aria-label="${chatExpanded?'Collapse chat':'Expand chat'}" aria-expanded="${chatExpanded}">${chatExpanded?'Collapse':'Expand'}</button><button id="close-chat" aria-label="Close chat">${icon('close')}</button></div></div><div class="drawer-body">${coachPage(true)}</div>`:coachPage();$('#chat-drawer').classList.toggle('expanded',chatExpanded);$('#close-chat')?.addEventListener('click',()=>closeChat());$('#expand-chat')?.addEventListener('click',()=>{chatExpanded=!chatExpanded;renderChat();$('#expand-chat')?.focus();});bindChat();const scroll=$('#chat-scroll');if(scroll)scroll.scrollTop=scroll.scrollHeight;}
const walkthrough=createWalkthrough({page:route,navigate:href=>go(href,false,true),speak:text=>voice.speak(text,true),stopSpeech:()=>voice.stop()});
function openHelp(){speech.stop();const dialog=$('#help-dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="help-title">Learn Home Accounts</h2><button type="button" id="close-help" aria-label="Close help">${icon('close')}</button></div><div class="dialog-body"><p>Follow a guided walkthrough with highlighted controls, clear instructions, and optional spoken steps.</p><label class="check"><input id="tour-spoken" type="checkbox" ${voice.canSpeak?'':'disabled'}>Read steps aloud using browser speech</label><p class="field-hint">Your browser may use its speech provider. These fixed help instructions include no financial records.</p><div class="actions"><button id="tour-page" class="primary">Guide me through this page</button><button id="tour-app" ${state.setup_complete?'':'disabled'}>Tour the whole app</button></div><p class="field-hint">The page tour preserves your form. The full tour navigates to other pages; finish or discard unsaved forms first. This is an interactive walkthrough, not a recorded video.</p></div>`;dialog.showModal();$('#close-help').onclick=()=>dialog.close();for(const [id,full] of [['tour-page',false],['tour-app',true]])$('#'+id).onclick=()=>{const spoken=$('#tour-spoken').checked;dialog.close();walkthrough.start(full,spoken);};}

function bindEntry(){if($('#entry-form')){bindCategoryForm($('#entry-form'));$('#entry-form').onsubmit=event=>{event.preventDefault();action(async()=>{const row=recordValues(event.target);openReview(await api('/api/proposal',{kind:'add',rows:[row],...(row.split?{split:{amount:row.split_amount,category:row.split_category,subcategory:row.split_subcategory}}:{})}));},event.submitter);};const mode=form=>{const show=form==='form';$('#entry-form').hidden=!show;$('#sentence-form').hidden=show;$('#form-tab').setAttribute('aria-selected',String(show));$('#sentence-tab').setAttribute('aria-selected',String(!show));};$('#form-tab').onclick=()=>mode('form');$('#sentence-tab').onclick=()=>mode('sentence');$('#sentence-form').onsubmit=event=>{event.preventDefault();action(async()=>{const result=await api('/api/chat',{text:$('#sentence').value,currency:scope.currency,month:scope.month,reference_date:state.today,use_ai:false});if(result.review)openReview(result.review);else toast(result.answer);},event.submitter);};}}
function bindChat(){
 $('#chat-settings-toggle')?.addEventListener('click',()=>{chatSettingsOpen=!chatSettingsOpen;renderChat();$('#chat-settings-toggle')?.focus();});
 $('#coach-ai')?.addEventListener('change',event=>{useAI=event.target.checked;renderChat();});
 $('#chat-text')?.addEventListener('input',event=>{chatDraft=event.target.value;speech.update();});
 $('#chat-text')?.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();if(!speech.active)void sendChat(chatDraft.trim());}});
 $('#chat-form')?.addEventListener('submit',event=>{event.preventDefault();void sendChat(chatDraft.trim());});
 $$('[data-prompt]').forEach(button=>button.onclick=()=>void sendChat(button.dataset.prompt));
 $$('[data-chat-review]').forEach(button=>button.onclick=()=>openReview(chat[Number(button.dataset.chatReview)].review));
 $$('[data-read-reply]').forEach(button=>button.onclick=()=>speech.read(chat[Number(button.dataset.readReply)].content,Number(button.dataset.readReply)));
 speech.bind();
}

