 if($('[data-overview-charts]'))bindOverviewCharts(document,overviewChartData(),href=>action(()=>go(href)));

 if($('#transaction-grid')){const standard=['date','type','description','category','subcategory','amount','currency','account'];const columns=standard.map(key=>({key,label:state.schema.fields.find(f=>f.key===key)?.label||key,numeric:key==='amount'}));columns.push(...state.schema.fields.filter(f=>f.included&&f.key.startsWith('custom_')).map(f=>({key:f.key,label:f.label,numeric:f.type==='Number'})));mountTransactionGrid($('#transaction-grid'),{records:gridRecords,columns,escape:E,newRecordIds});}

 $('#menu-open')?.addEventListener('click',()=>{$('#navigation').classList.add('open');$('.workspace').inert=true;$('.bottom-nav').inert=true;$('#menu-open').setAttribute('aria-expanded','true');$('#menu-close').focus();});$('#menu-close')?.addEventListener('click',()=>{menuClose();$('#menu-open').focus();});
 $('#theme-cycle')?.addEventListener('click',()=>action(async()=>{const modes=['light','dark','bright'];state.settings=await api('/api/settings',{theme:modes[(modes.indexOf(state.settings.theme)+1)%3]});document.documentElement.dataset.theme=state.settings.theme;toast('Visual mode: '+state.settings.theme);}));
 $$('[data-theme-choice]').forEach(b=>b.onclick=()=>action(async()=>{state.settings=await api('/api/settings',{theme:b.dataset.themeChoice});document.documentElement.dataset.theme=state.settings.theme;$$('[data-theme-choice]').forEach(n=>n.setAttribute('aria-pressed',n===b?'true':'false'));toast('Visual mode saved.');},b));
 $('#home-form')?.addEventListener('submit',event=>{event.preventDefault();action(async()=>{state.settings=await api('/api/settings',{home:$('[name=home]',event.target).value});toast('Home preference saved.');},event.submitter);});
 bindCurrencyPicker(document,state.currencies,scope.currency,currency=>action(async()=>{speech.stop();scope={currency,month:null};state.settings=await api('/api/settings',{currency});const url=new URL(location.href);url.searchParams.delete('month');url.searchParams.delete('currency');history.replaceState({},'',url.pathname+url.search);initialScope();await render();}));
 $('#scope-month')?.addEventListener('change',event=>action(async()=>{if(!event.target.value)return;speech.stop();scope.month=event.target.value;const url=new URL(location.href);url.searchParams.set('month',scope.month);url.searchParams.set('currency',scope.currency);history.replaceState({scope},'',url.pathname+url.search);await render();}));
