let renderVersion=0;
async function render(){const generation=++renderVersion;let page=route();if(!state.setup_complete&&page!=='setup'){history.replaceState({},'','/setup');page='setup';}if(page==='setup'&&!state.setup_complete){$('#app').innerHTML=`<div class="onboarding"><a class="brand setup-brand" href="/setup" data-route><span class="brand-mark">${icon('home')}</span>Home Accounts</a><div class="setup-help"><button id="help-walkthrough">Help walkthrough</button></div><main id="main"><div id="page-error" class="notice error" role="alert" hidden></div>${setupPage()}</main></div>`;bindPage();return;}if(location.pathname==='/'){history.replaceState({},'','/'+page);}if(scope.currency&&['overview','budgets','planning'].includes(page)){const result=await api('/api/overview?'+new URLSearchParams({currency:scope.currency,month:scope.month}));if(generation!==renderVersion)return;report=result;}$('#app').innerHTML=shell();const views={overview:overviewPage,transactions:transactionPage,budgets:budgetPage,entry:entryPage,import:importPage,setup:setupPage,settings:settingsPage,coach:coachPage,planning:planningPage,learn:learnPage};$('#page').innerHTML=!scope.currency&&!['settings','setup','import','learn'].includes(page)?currencyRequired():(views[page]||overviewPage)();document.title=(routes.find(r=>r[0]===page)?.[1]||'Field setup')+' · Home Accounts';bindPage();if(chatDrawerOpen)renderChat();}
document.addEventListener('click',event=>{const anchor=event.target.closest('a[data-route]');const target=event.target.closest('[data-go]');if((anchor||target)&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey){event.preventDefault();const href=anchor?.getAttribute('href')||target.dataset.go;if(href==='/entry'&&['overview','transactions'].includes(route())&&!anchor?.closest('.sidebar,.bottom-nav')){openEntry();return;}history.replaceState({scope},'',location.href);action(()=>go(href));return;}const edit=event.target.closest('[data-edit]');if(edit){openEdit(edit.dataset.edit);return;}const remove=event.target.closest('[data-delete]');if(remove){action(async()=>openReview(await api('/api/proposal',{kind:'delete',id:remove.dataset.delete})),remove);return;}const budget=event.target.closest('[data-budget]');if(budget)openBudget(state.budgets.find(b=>b.id===budget.dataset.budget));});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){menuClose();if(chatDrawerOpen&&!document.querySelector('dialog[open]'))closeChat();}if(event.key==='Tab'&&$('#navigation')?.classList.contains('open')){const nodes=$$('a,button', $('#navigation')).filter(n=>n.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){last.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===last){first.focus();event.preventDefault();}}});
$('#entry-dialog').addEventListener('close',()=>$('#entry-dialog').replaceChildren());
window.addEventListener('beforeunload',()=>{speech.stop();});
window.addEventListener('popstate',event=>{speech.stop();walkthrough.stop();closeChat(false);$('#entry-dialog').close();scope=event.state?.scope||{currency:null,month:null};initialScope();action(render);});
(async()=>{try{await refresh();await render();}catch(error){$('#app').innerHTML=`<main class="boot"><h1>Could not open your workspace</h1><p>${E(error.message)}</p><p>Keep your data backup and restart the local server.</p></main>`;}})();
